),
atual as (
  select to_char(make_date(reference_year, reference_month, 1), 'YYYY-MM') as ym,
         count(*) as linhas, round(sum(valor), 2) as fat, round(coalesce(sum(rl), 0), 2) as rl, round(coalesce(sum(mp), 0), 2) as mp
  from public.comercial_realizado_ledger_entries
  where make_date(reference_year, reference_month, 1) between date '2023-01-01' and date '2026-09-01'
  group by 1
)
select e.ym, e.linhas as linhas_arquivo, a.linhas as linhas_ledger, e.fat as fat_arquivo, a.fat as fat_ledger,
       (a.linhas = e.linhas and abs(a.fat - e.fat) < 0.05 and abs(a.rl - e.rl) < 0.05 and abs(a.mp - e.mp) < 0.05) as ok
from esperado e left join atual a using (ym)
order by e.ym;

-- Meses fora do arquivo (devem permanecer como estavam): 2026-10 e 2026-11
select reference_year, reference_month, origem, count(*) from public.comercial_realizado_ledger_entries
where make_date(reference_year, reference_month, 1) > date '2026-09-01' group by 1, 2, 3 order by 1, 2, 3;

-- Vendedores novos criados como "historico" pela carga
select codigo, nome, situacao from public.comercial_vendedores where nome like 'Vendedor historico%' order by codigo;
